-- SYNC-04 L8: read-only catalog inspection, no user data or mutation.
with t as (select c.relname name,jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'auth_select',has_table_privilege('authenticated',c.oid,'SELECT'),'auth_insert',has_table_privilege('authenticated',c.oid,'INSERT'),'auth_update',has_table_privilege('authenticated',c.oid,'UPDATE'),'auth_delete',has_table_privilege('authenticated',c.oid,'DELETE')) datum from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and c.relname in ('notes','profiles','review_events','review_retractions','client_mutation_receipts')),
p as (select tablename||':'||policyname name,jsonb_build_object('table',tablename,'name',policyname,'cmd',cmd,'roles',roles::text,'qual',qual,'check',with_check) datum from pg_policies where schemaname='public' and tablename in ('notes','profiles','review_events','review_retractions','client_mutation_receipts')),
f as (select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' name,jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definer',p.prosecdef,'body_md5',md5(pg_get_functiondef(p.oid)),'anon_exec',has_function_privilege('anon',p.oid,'EXECUTE'),'auth_exec',has_function_privilege('authenticated',p.oid,'EXECUTE'),'public_exec',has_function_privilege('public',p.oid,'EXECUTE')) datum from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','lemma_private') and p.proname in ('commit_note','commit_profile','publish_study_plan'))
select jsonb_build_object('tables',(select jsonb_agg(datum order by name) from t),'policies',(select jsonb_agg(datum order by name) from p),'functions',(select jsonb_agg(datum order by name) from f),'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations))::text as snapshot;
